"""Problemas originales con datos nuevos; modelos académicos y soluciones SI."""
from pathlib import Path
import math,json
from models import *
ROOT=Path(__file__).resolve().parents[1]
def num(x):
 if abs(x)>=1e5 or (x and abs(x)<.001):
  a,b=rf'{x:.6e}'.split('e');return a+r'\times10^{'+str(int(b))+'}'
 return rf'{x:.7g}'
def q(x,u=''):return '$'+num(x)+(r'\,\mathrm{'+u+'}' if u else '')+'$'
def make(key,ch,diff,title,prompt,giv,unknown,assumptions,model,eqs,steps,result,interpret,checks,limits,tests):
 return dict(key=key,ch=ch,difficulty=diff,title=title,prompt=prompt,given=giv,unknown=unknown,assumptions=assumptions,model=model,equations=eqs,steps=steps,result=result,interpretation=interpret,checks=checks,limitations=limits,tests=tests)
def g(s,v,u,m):return dict(symbol=s,value=v,unit=u,meaning=m)
def t(expr,val,unit='dimensionless',sym=None,units=None):return dict(expression=expr,expected=val,unit=unit,symbolic=sym,symbol_units=units)

def thrust(key,ch,diff,z):
 md=1.6+.13*z;ve=2200+27*z;pe=(40+z)*1000;pa=(82-z)*1000;Ae=.009+.0002*z;kin=md*ve;press=(pe-pa)*Ae;F=kin+press;vac=kin+pe*Ae;c=F/md;isp=c/G0
 return make(key,ch,diff,'Momento y presión en dos ambientes',rf'Una descarga académica uniforme tiene caudal {q(md,"kg/s")}, rapidez {q(ve,"m/s")}, presión de salida {q(pe/1000,"kPa")} y área {q(Ae,"m^2")}. El ambiente tiene {q(pa/1000,"kPa")}. Determine empuje, velocidad efectiva e impulso específico, y repita para vacío conservando el estado interno.',[g('mdot',md,'kg/s','Caudal total'),g('ve',ve,'m/s','Rapidez axial'),g('pe',pe,'Pa','Salida'),g('pa',pa,'Pa','Ambiente'),g('Ae',Ae,'m^2','Área de salida')],'F, c, Isp y cambio a vacío',['Estacionario, axial y salida uniforme.','Estado interno invariable y flujo adherido supuesto; no se prueba su régimen con los datos disponibles.'],'Balance de momento respecto al ambiente',[r'F=\dot m v_e+(p_e-p_a)A_e',r'c=F/\dot m,\quad I_{sp}=c/g_0',r'F_v-F=p_aA_e'],[rf'La contribución cinética es {q(md)} por {q(ve)}, igual a {q(kin,"N")}. La presión aporta $({num(pe)}-{num(pa)}){num(Ae)}={num(press)}$ N.',rf'Sumar ambas da {q(F,"N")}. Dividir por {q(md,"kg/s")} produce {q(c,"m/s")}; dividir después por $g_0$ produce {q(isp,"s")}.',rf'En vacío se conserva la descarga y se elimina únicamente $-p_aA_e$. Resulta {q(vac,"N")}, con {q(vac/(md*G0),"s")}. No se impone adaptación para efectuar ninguno de los dos cálculos.'],rf'$F={num(F)}$ N; $c={num(c)}$ m/s; $I_{{sp}}={num(isp)}$ s; $F_v={num(vac)}$ N.','La rapidez física permanece fija, pero el impulso específico cambia con el ambiente porque incluye el empuje de presión. Un cociente de presiones no se deduce de haber calculado un empuje positivo.',rf'La diferencia a vacío es {q(vac-F,"N")} y coincide con $p_aA_e$. Recuperar $g_0I_{{sp}}$ debe dar $F/\dot m$, no necesariamente $v_e$.','No se han establecido dimensiones de garganta ni un mapa de régimen; no es una predicción de separación ni de estabilidad de un motor.',[t(rf'{md}*{ve}+({pe}-{pa})*{Ae}',F,'N','mdot*ve+(pe-pa)*Ae',{'mdot':'kg/s','ve':'m/s','pe':'Pa','pa':'Pa','Ae':'m^2'}),t(rf'{F}/({md}*{G0})',isp,'s')])

def thermo(key,ch,diff,z):
 gam=1.3;mol=23+.1*z;R=RU/mol;T0=2400+10*z;p0=2.5e6;M=2+.025*z;rt=stagnation_ratios(M,gam);T=T0*rt['T_T0'];p=p0*rt['p_p0'];cp=gam*R/(gam-1);v=M*math.sqrt(gam*R*T)
 return make(key,ch,diff,'Dos rutas para la velocidad de una expansión',rf'Un gas académico de $\gamma={gam}$ y masa molar {q(mol,"kg/kmol")} tiene $T_0={num(T0)}$ K y $p_0=2.50$ MPa. Una sección isentrópica alcanza $M={num(M)}$. Halle $R,c_p,T,p,u$ y verifique energía.',[g('gamma',gam,'dimensionless','Exponente constante'),g('Mmol',mol,'kg/kmol','Masa molar'),g('T0',T0,'K','Temperatura total'),g('p0',p0,'Pa','Presión total'),g('M',M,'dimensionless','Mach')],'Propiedades específicas y estado estático',['Gas caloríficamente perfecto de composición fija.','Expansión adiabática reversible, sin trabajo ni altura.'],'Energía y relaciones de remanso',[r'R=R_u/\mathcal M,\quad c_p=\gamma R/(\gamma-1)',r'T=T_0/[1+(\gamma-1)M^2/2]',r'p=p_0(T/T_0)^{\gamma/(\gamma-1)}',r'u=M\sqrt{\gamma RT}=\sqrt{2c_p(T_0-T)}'],[rf'Se usa $R_u=8314.462618$ J/(kmol K), coherente con kg/kmol. Así $R={num(R)}$ J/(kg K) y $c_p={num(cp)}$ J/(kg K).',rf'El factor de remanso es {q(1/rt["T_T0"])}. Dividir $T_0$ da {q(T,"K")}; la potencia isentrópica da {q(p/1000,"kPa")}.',rf'Con la temperatura estática, la ruta acústica da {q(v,"m/s")}. La ruta energética usa el descenso $c_p(T_0-T)$ y produce el mismo valor. Usar $T_0$ dentro del sonido de la sección daría otra rapidez incompatible.'],rf'$T={num(T)}$ K; $p={num(p)}$ Pa; $u={num(v)}$ m/s.','El gas acelera y enfría, pero su temperatura total permanece fija. La presión total se mantiene sólo porque se ha supuesto isentropía.',rf'$c_pT+u^2/2=c_pT_0={num(cp*T0)}$ J/kg. La entropía calculada mediante $c_p\ln(T/T_0)-R\ln(p/p_0)$ es cero dentro de redondeo.','No se modela química ni variación calorífica; gamma es un dato académico, no una propiedad universal de productos reales.',[t(rf'{RU}/{mol}',R,'J/(kg*K)'),t(rf'{M}*sqrt({gam}*{R}*{T})',v,'m/s'),t(rf'{cp}*{T}+{v}**2/2',cp*T0,'J/kg')])

def uncertainty(key,ch,diff,z):
 F=4000+50*z;md=1.7+.02*z;uf=.01+.0002*z;um=.007;r=.25;u=math.sqrt(uf*uf+um*um-2*r*uf*um);isp=F/(md*G0)
 return make(key,ch,diff,'Incertidumbre de un cociente correlacionado',rf'Se miden $F={num(F)}$ N y $\dot m={num(md)}$ kg/s. Sus incertidumbres estándar relativas son {q(uf*100)}\,\% y 0.7\,\%, con correlación $r=0.25$. Estime $I_{{sp}}$ y su incertidumbre linealizada; compare con asumir independencia.',[g('F',F,'N','Empuje'),g('mdot',md,'kg/s','Caudal'),g('uFrel',uf,'dimensionless','Incertidumbre relativa'),g('umrel',um,'dimensionless','Incertidumbre relativa'),g('corr',r,'dimensionless','Correlación')],'Impulso específico e incertidumbre estándar',['Perturbaciones pequeñas y modelo diferenciable.','g0 convencional; correlación proporcionada.'],'Propagación mediante gradiente y covarianza',[r'I_{sp}=F/(g_0\dot m)',r'(u_I/I_{sp})^2=u_F^2/F^2+u_m^2/\dot m^2-2r(u_F/F)(u_m/\dot m)'],[rf'Las sensibilidades son $\partial I/\partial F=1/(g_0\dot m)$ y $\partial I/\partial\dot m=-F/(g_0\dot m^2)$. Sus signos opuestos explican el signo negativo de la covarianza.',rf'La sustitución da $I_{{sp}}={num(isp)}$ s y $u_I/I_{{sp}}=\sqrt{{{num(uf)}^2+{num(um)}^2-2({num(r)})({num(uf)})({num(um)})}}={num(u)}$.',rf'Multiplicar por el valor central da {q(isp*u,"s")}. Si se impone $r=0$, la incertidumbre relativa sería {q(math.hypot(uf,um)*100)}\,\%; esa diferencia no es una mejora del sensor sino un cambio del modelo de correlación.'],rf'$I_{{sp}}={num(isp)}$ s; $u(I_{{sp}})={num(isp*u)}$ s.','Las variaciones comunes de empuje y caudal pueden compensarse parcialmente en su cociente. La incertidumbre instrumental no cuantifica por sí sola error de modelo físico.',r'La matriz de correlación es admisible porque $|r|\leq1$. El radicando es no negativo y el resultado conserva unidad de segundos.','No es un intervalo de confianza expandido; no se asigna cobertura sin una distribución y factor definidos.',[t(rf'{F}/({md}*{G0})',isp,'s'),t(rf'sqrt({uf}**2+{um}**2-2*{r}*{uf}*{um})',u)])

def nozzle_case(key,ch,diff,z):
 gam=1.32;R=350.;Tc=2500+5*z;pc=1.8e6+2e4*z;At=.00025+z*.000002;eps=3+.04*z;pa=25000.;v=nozzle(gam,R,Tc,pc,At,eps,pa);msub=mach_area(eps,gam,'subsonic');start=stagnation_ratios(msub,gam)['p_p0'];shockexit=v['pe']/pc*shock(v['Me'],gam)['p2_p1'];vac=v['F']+pa*v['Ae']
 return make(key,ch,diff,'Tobera de Laval: geometría, régimen y prestaciones',rf'Un modelo de gas tiene $\gamma={gam}$, $R=350$ J/(kg K), $T_c={num(Tc)}$ K y $p_c={num(pc/1e6)}$ MPa, magnitudes totales. La garganta tiene {q(At,"m^2")} y $A_e/A_t={num(eps)}$. Para ambiente de 25 kPa, obtenga Mach, estado de salida, caudal, $c^*$, $C_F$, empuje e $I_{{sp}}$. Compruebe los umbrales ideales y calcule la prestación en vacío.',[g('gamma',gam,'dimensionless','Exponente'),g('Rgas',R,'J/(kg*K)','Constante específica'),g('Tc',Tc,'K','Temperatura total'),g('pc',pc,'Pa','Presión total'),g('At',At,'m^2','Garganta'),g('epsilon',eps,'dimensionless','Expansión'),g('pa',pa,'Pa','Ambiente')],'Estado, descarga, régimen ideal y prestaciones',['Gas caloríficamente perfecto.','Garganta ahogada, salida candidata supersónica; separación viscosa fuera del modelo.'],'Área-Mach, conservación de energía y momento',[r'\varepsilon=\frac1{M_e}\left[\frac2{\gamma+1}(1+\frac{\gamma-1}2M_e^2)\right]^{(\gamma+1)/[2(\gamma-1)]}',r'T_e=T_c/[1+(\gamma-1)M_e^2/2],\quad p_e=p_c(T_e/T_c)^{\gamma/(\gamma-1)}',r'\dot m=p_cA_t/c^*,\quad F=\dot m v_e+(p_e-p_a)A_e',r'C_F=F/(p_cA_t),\quad I_{sp}=F/(g_0\dot m)'],[rf'La raíz supersónica es $M_e={num(v["Me"])}$. La raíz subsónica de igual área es {q(msub)}. De ella resulta primer bloqueo a $p_b/p_c={num(start)}$; un choque normal en salida daría {q(shockexit)}.',rf'El ambiente tiene $p_a/p_c={num(pa/pc)}$, por debajo del umbral de choque en salida. Es compatible con divergente supersónico en el modelo unidimensional. Eso no comprueba separación viscosa.',rf'La relación térmica da {q(v["Te"],"K")} y la isentrópica {q(v["pe"],"Pa")}. Con la temperatura estática, $v_e={num(v["ve"])}$ m/s. El área de salida es $\varepsilon A_t={num(v["Ae"])}$ m$^2$.',rf'El caudal crítico se obtiene de $c^*={num(v["cstar"])}$ m/s, luego $\dot m={num(v["mdot"])}$ kg/s. El término cinético es {q(v["mdot"]*v["ve"],"N")} y el de presión {q((v["pe"]-pa)*v["Ae"],"N")}.',rf'La suma produce {q(v["F"],"N")}; las divisiones definitorias dan $C_F={num(v["CF"])}$ e $I_{{sp}}={num(v["Isp"])}$ s. Para vacío se suma $p_aA_e$ y resulta {q(vac,"N")}, con $I_{{sp,v}}={num(vac/(v["mdot"]*G0))}$ s.'],rf'$M_e={num(v["Me"])}$; $\dot m={num(v["mdot"])}$ kg/s; $F={num(v["F"])}$ N; $C_F={num(v["CF"])}$; $I_{{sp}}={num(v["Isp"])}$ s.','La geometría fija una presión de salida que no se ha igualado al ambiente. La denominación subexpandida o sobreexpandida se decide comparando esas presiones; el vacío cambia empuje de presión.','Sustituir Mach debe recuperar la relación de áreas. El caudal calculado con densidad, rapidez y área de salida coincide con el de garganta; $C_Fc^*=g_0I_{sp}$. Las dos rutas de velocidad cierran energía.','No se predicen capa límite, cargas laterales ni química. La compatibilidad de umbrales es del modelo inviscido y no una garantía de adherencia real.',[t(rf'{v["mdot"]}*{v["ve"]}+({v["pe"]}-{pa})*{v["Ae"]}',v['F'],'N','mdot*ve+(pe-pa)*Ae',{'mdot':'kg/s','ve':'m/s','pe':'Pa','pa':'Pa','Ae':'m^2'}),t(rf'{pc}*{At}/{v["cstar"]}',v['mdot'],'kg/s'),t(rf'{v["CF"]}*{v["cstar"]}',v['Isp']*G0,'m/s')])

def shock_case(key,ch,diff,z):
 M=1.8+.03*z;gam=1.4;R=287.;T1=400+z;p1=30000.;s=shock(M,gam);T2=T1*s['T2_T1'];p2=p1*s['p2_p1'];u1=M*math.sqrt(gam*R*T1);u2=s['M2']*math.sqrt(gam*R*T2);cp=gam*R/(gam-1);ds=-R*math.log(s['p02_p01'])
 return make(key,ch,diff,'Salto normal y degradación de presión total',rf'Un gas académico con $\gamma=1.4$, $R=287$ J/(kg K), $M_1={num(M)}$, $T_1={num(T1)}$ K y $p_1=30$ kPa cruza un choque normal estacionario. Determine $M_2,p_2,T_2$, relación de presiones totales y generación específica de entropía.',[g('M1',M,'dimensionless','Mach anterior'),g('T1',T1,'K','Temperatura anterior'),g('p1',p1,'Pa','Presión anterior'),g('gamma',gam,'dimensionless','Exponente'),g('Rgas',R,'J/(kg*K)','Constante')],'Estado posterior y entropía',['Gas caloríficamente perfecto; choque plano.','Adiabático y sin trabajo; no se conserva presión total.'],'Rankine--Hugoniot y segunda ley',[r'\rho_1u_1=\rho_2u_2,\quad p_1+\rho_1u_1^2=p_2+\rho_2u_2^2',r'h_1+u_1^2/2=h_2+u_2^2/2',r'M_2^2=\frac{1+(\gamma-1)M_1^2/2}{\gamma M_1^2-(\gamma-1)/2}',r'\Delta s=-R\ln(p_{02}/p_{01})'],[rf'Eliminar velocidad posterior mediante continuidad permite obtener $\rho_2/\rho_1={num(s["rho2_rho1"])}$. El balance de momento da $p_2/p_1={num(s["p2_p1"])}$ y la ecuación de estado $T_2/T_1={num(s["T2_T1"])}$.',rf'Se obtiene $M_2={num(s["M2"])}$, $p_2={num(p2)}$ Pa y $T_2={num(T2)}$ K. Las velocidades son {q(u1,"m/s")} y {q(u2,"m/s")}, respectivamente.',rf'Calcular remanso a cada lado produce $p_{{02}}/p_{{01}}={num(s["p02_p01"])}$. Por tanto $\Delta s=-{num(R)}\ln({num(s["p02_p01"])})={num(ds)}$ J/(kg K).'],rf'$M_2={num(s["M2"])}$; $p_2={num(p2)}$ Pa; $T_2={num(T2)}$ K; $\Delta s={num(ds)}$ J/(kg K).','La temperatura estática aumenta al convertir movimiento en entalpía. La energía total se conserva, pero la presión total baja: no es una expansión isentrópica.',rf'Las entalpías totales coinciden en {q(cp*T1+u1*u1/2,"J/kg")}. La ruta $c_p\ln(T_2/T_1)-R\ln(p_2/p_1)$ recupera la misma entropía positiva.','La disociación, calor a pared y frentes oblicuos no están modelados. El resultado no localiza el choque dentro de una tobera.',[t(rf'{cp}*{T2}+{u2}**2/2',cp*T1+u1*u1/2,'J/kg'),t(rf'-{R}*log({s["p02_p01"]})',ds,'J/(kg*K)')])

def solid_case(key,ch,diff,z):
 n=.32+.002*z;ar=1.12+.01*z;tr=1.02;P=(ar/tr)**(1/(1-n));mdratio=P*tr;Fratio=mdratio
 return make(key,ch,diff,'Superficie y garganta variables: modelo normalizado',rf'En un modelo académico de regresión se conserva densidad, temperatura y $c^*$. La ley es $r_b/r_{{ref}}=(p_c/p_{{ref}})^n$, con $n={num(n)}$. Entre dos estados el área activa se multiplica por {q(ar)} y la garganta por 1.02. Calcule razones de presión, regresión y caudal. Determine la razón de empuje si $C_F$ se mantiene.',[g('n',n,'dimensionless','Exponente local'),g('area_ratio',ar,'dimensionless','Razón de área activa'),g('throat_ratio',tr,'dimensionless','Razón de garganta')],'Cocientes de presión, regresión, masa y empuje',['Cuasiestacionario; descarga ahogada.','Propiedades y CF fijos; ejemplo normalizado sin asignación a propulsante real.'],'Equilibrio de generación y descarga',[r'\rho_pA_br_{ref}(p_c/p_{ref})^n=p_cA_t/c^*',r'P^{1-n}=\frac{A_{b,2}/A_{b,1}}{A_{t,2}/A_{t,1}}',r'P=(\alpha/\tau)^{1/(1-n)},\quad r_{b,2}/r_{b,1}=P^n',r'\dot m_2/\dot m_1=P\tau,\quad F_2/F_1=P\tau\ (C_F\ fijo)'],[rf'Dividir los equilibrios elimina los parámetros dimensionales comunes. Queda $P^{{1-{num(n)}}}={num(ar)}/1.02$. Se despeja elevando a $1/(1-n)$, porque $n<1$.',rf'Sustituir da $P={num(P)}$. La regresión aumenta por un factor $P^n={num(P**n)}$. El caudal generado cambia por $\alpha P^n={num(ar*P**n)}$.',rf'La descarga produce independientemente $P\tau={num(mdratio)}$, igual al caudal generado. Con $C_F$ fijo, $F=C_Fp_cA_t$ da el mismo factor de empuje; usar sólo $P$ omitiría el cambio de garganta.'],rf'$p_2/p_1={num(P)}$; $r_{{b,2}}/r_{{b,1}}={num(P**n)}$; $\dot m_2/\dot m_1=F_2/F_1={num(mdratio)}$.','El aumento de garganta compensa parte del efecto de área activa. La hipótesis de CF fijo es adicional y podría fallar si cambia la expansión o presión ambiente.',rf'El cierre $\alpha P^n=P\tau$ se verifica por ambas rutas. Todos los cocientes son adimensionales. Para $\alpha=\tau=1$ se recupera equilibrio inicial.','No se incluye almacenamiento, erosión predictiva, cinética de superficie ni inestabilidad acústica. Un exponente local no es una garantía de estabilidad real.',[t(rf'({ar}/{tr})**(1/(1-{n}))',P),t(rf'{ar}*{P}**{n}',mdratio),t(rf'{P}*{tr}',mdratio)])

def mixture(key,ch,diff,z):
 md=4+.1*z;ratio=2.4+.02*z;duration=80+z;rhoo=1100.;rhof=850.;mf=md/(1+ratio);mo=md-mf;vol=(mf/rhof+mo/rhoo)*duration;dens=md*duration/vol
 return make(key,ch,diff,'Dos corrientes, duración y volumen almacenado',rf'Un sistema académico de dos líquidos consume {q(md,"kg/s")} durante {q(duration,"s")}, con relación másica oxidante/combustible {q(ratio)}. A sus estados de referencia, las densidades son 1100 y 850 kg/m$^3$. Determine caudales separados, masas consumidas, volúmenes y densidad equivalente.',[g('mdot',md,'kg/s','Caudal total'),g('ratio',ratio,'dimensionless','Relación de mezcla'),g('duration',duration,'s','Duración'),g('rhoo',rhoo,'kg/m^3','Densidad oxidante'),g('rhof',rhof,'kg/m^3','Densidad combustible')],'Caudales, masas y volúmenes',['Régimen constante y sólo dos corrientes.','Densidades de referencia constantes; no se incluyen espacio de gas, estructura ni reservas.'],'Conservación de masa y volumen de líquidos separados',[r'\dot m_f=\dot m/(1+\mathcal R),\quad \dot m_o=\mathcal R\dot m_f',r'm_i=\dot m_it,\quad V_i=m_i/\rho_i',r'\rho_{eq}=(1+\mathcal R)/(1/\rho_f+\mathcal R/\rho_o)'],[rf'Se despeja combustible de $\dot m=(1+\mathcal R)\dot m_f$. Resulta {q(mf,"kg/s")}; multiplicar por la relación da {q(mo,"kg/s")} de oxidante.',rf'Integrar caudales constantes durante {q(duration,"s")} da {q(mf*duration,"kg")} y {q(mo*duration,"kg")}. Dividir por densidades produce {q(mf*duration/rhof,"m^3")} y {q(mo*duration/rhoo,"m^3")}.',rf'La suma de volúmenes es {q(vol,"m^3")}; dividir la masa total por ese volumen da {q(dens,"kg/m^3")}. No se ha promediado aritméticamente densidades.'],rf'$\dot m_f={num(mf)}$ kg/s; $\dot m_o={num(mo)}$ kg/s; $V_p={num(vol)}$ m$^3$; $\rho_{{eq}}={num(dens)}$ kg/m$^3$.','La densidad equivalente es masa dividida por suma de volúmenes separados; no implica mezcla física en un depósito. La relación dada es másica y no coincide con relación volumétrica.',rf'Los caudales suman {q(md,"kg/s")} y su cociente es {q(ratio)}. La densidad equivalente queda entre ambas densidades positivas.','No se predice combustión ni prestación. Si la mezcla o caudal varían, cada corriente se integra de forma independiente.',[t(rf'{md}/(1+{ratio})',mf,'kg/s','mdot/(1+ratio)',{'mdot':'kg/s','ratio':'dimensionless'}),t(rf'({mf}/{rhof}+{mo}/{rhoo})*{duration}',vol,'m^3')])

def heat(key,ch,diff,z):
 hg=1800+10*z;hl=5000.;delta=.0015;k=18.;Taw=1100+2*z;Tl=290.;a=1/hg;b=delta/k;c=1/hl;flux=(Taw-Tl)/(a+b+c);Tg=Taw-flux*a;Tw=Tl+flux*c;A=.012;md=.15;cp=2200.;Q=flux*A;rise=Q/(md*cp)
 return make(key,ch,diff,'Pared y refrigerante: cierre térmico',rf'Una pared plana académica tiene espesor 1.50 mm y $k=18$ W/(m K). El gas tiene $T_{{aw}}={num(Taw)}$ K y $h_g={num(hg)}$ W/(m$^2$ K); el refrigerante, 290 K y $h_l=5000$ W/(m$^2$ K). Para área 0.012 m$^2$, caudal 0.15 kg/s y $c_p=2200$ J/(kg K), obtenga flujo, temperaturas de caras y aumento térmico del refrigerante.',[g('hg',hg,'W/(m^2*K)','Convección gas'),g('hl',hl,'W/(m^2*K)','Convección líquido'),g('delta',delta,'m','Espesor'),g('k',k,'W/(m*K)','Conductividad'),g('Taw',Taw,'K','Recuperación'),g('Tl',Tl,'K','Refrigerante')],'q, temperaturas de pared y potencia',['Estacionario unidimensional, propiedades constantes.','Sin radiación ni almacenamiento; temperatura de refrigerante representativa.'],'Resistencias térmicas y balance de entalpía',[r'q^{\prime\prime}=(T_{aw}-T_l)/(1/h_g+\delta/k+1/h_l)',r'T_{wg}=T_{aw}-q^{\prime\prime}/h_g,\quad T_{wl}=T_l+q^{\prime\prime}/h_l',r'\dot Q=q^{\prime\prime}A,\quad \Delta T_l=\dot Q/(\dot m_lc_{p,l})'],[rf'Las resistencias suman {q(a+b+c,"m^2K/W")}. Dividir el salto {q(Taw-Tl,"K")} da {q(flux,"W/m^2")}.',rf'La caída del lado gas es {q(flux*a,"K")}, la de pared {q(flux*b,"K")} y la del refrigerante {q(flux*c,"K")}. Así las caras quedan a {q(Tg,"K")} y {q(Tw,"K")}.',rf'Multiplicar por área da {q(Q,"W")}. El balance del refrigerante produce $\Delta T={num(Q)}/(0.15\cdot2200)={num(rise)}$ K. Esa subida pequeña se compara con el salto gas-líquido para valorar la temperatura representativa inicial.'],rf'$q^{{\prime\prime}}={num(flux)}$ W/m$^2$; $T_{{wg}}={num(Tg)}$ K; $T_{{wl}}={num(Tw)}$ K; $\Delta T_l={num(rise)}$ K.','Las temperaturas metálicas se calculan entre las del gas y líquido. La potencia total y la temperatura local de pared son restricciones distintas.',rf'$h_g(T_{{aw}}-T_{{wg}})=k(T_{{wg}}-T_{{wl}})/\delta=h_l(T_{{wl}}-T_l)={num(flux)}$ W/m$^2$. El calor absorbido coincide con $\dot m c_p\Delta T$.','No se comprueban ebullición, resistencia del material ni geometría de un motor; si la subida del líquido fuese grande, habría que resolver la variación axial.',[t(rf'({Taw}-{Tl})/(1/{hg}+{delta}/{k}+1/{hl})',flux,'W/m^2','(Taw-Tl)/(1/hg+delta/k+1/hl)',{'Taw':'K','Tl':'K','hg':'W/(m^2*K)','hl':'W/(m^2*K)','delta':'m','k':'W/(m*K)'}),t(rf'{md}*{cp}*{rise}',Q,'W')])

def pump(key,ch,diff,z):
 md=2+.1*z;dp=(1.2+.02*z)*1e6;rho=1000.;eta=.72;P=md*dp/(rho*eta);etat=.8;etam=.95;dhi=220000.;mt=P/(etat*etam*dhi)
 return make(key,ch,diff,'Demanda de bomba y cierre de eje',rf'Una bomba académica eleva presión en {q(dp/1e6,"MPa")} para caudal {q(md,"kg/s")} de un líquido de densidad 1000 kg/m$^3$, con rendimiento 0.72. Una turbina dispone de salto isentrópico 220 kJ/kg, rendimiento 0.80 y transmisión 0.95. Halle potencia demandada y caudal de turbina para equilibrio de eje.',[g('mdot',md,'kg/s','Caudal líquido'),g('dp',dp,'Pa','Salto presión'),g('rho',rho,'kg/m^3','Densidad'),g('etap',eta,'dimensionless','Rendimiento bomba')],'Potencia y caudal de turbina',['Líquido incompresible; régimen estacionario.','Rendimientos definidos respecto al mismo balance; sin otros auxiliares.'],'Trabajo de presión y potencia de eje',[r'w_p=\Delta p/(\rho\eta_p),\quad P_p=\dot m w_p',r'P_t=\eta_m\dot m_t\eta_t\Delta h_{is}',r'\dot m_t=P_p/(\eta_m\eta_t\Delta h_{is})'],[rf'El trabajo hidráulico ideal es {q(dp/rho,"J/kg")}; dividir por 0.72 aumenta la demanda a {q(dp/(rho*eta),"J/kg")}. Multiplicar por caudal produce {q(P,"W")}.',rf'El salto útil entregado al eje por kg de gas de turbina es $0.95\cdot0.80\cdot220000={num(etam*etat*dhi)}$ J/kg. Dividir la demanda por ese valor da {q(mt,"kg/s")}.',rf'El salto se convirtió de kJ/kg a J/kg antes de sustituir. El rendimiento de bomba divide la demanda y el de turbina multiplica la capacidad: invertirlos permitiría obtener trabajo útil mayor que el disponible.'],rf'$P_p={num(P)}$ W; $\dot m_t={num(mt)}$ kg/s.','El balance energético cierra un eje idealizado, pero todavía faltan presiones que permitan la expansión y el destino de la corriente de turbina.',rf'$0.95\dot m_t0.80\Delta h_{{is}}={num(P)}$ W. Todos los rendimientos están entre cero y uno, y potencia tiene dimensión de trabajo por tiempo.','No se comprueba cavitación, velocidad de giro, resistencia ni cierre completo de un ciclo de motor.',[t(rf'{md}*{dp}/({rho}*{eta})',P,'W','mdot*dp/(rho*etap)',{'mdot':'kg/s','dp':'Pa','rho':'kg/m^3','etap':'dimensionless'}),t(rf'{P}/({etam}*{etat}*{dhi})',mt,'kg/s')])

def ep_case(key,ch,diff,z):
 P=1200+40*z;eta=.6;ve=18000+100*z;dur=36000+100*z;m0=450.;e=electric(P,eta,ve);mass=e['mdot']*dur;imp=e['F']*dur;dv=ve*math.log(m0/(m0-mass))
 return make(key,ch,diff,'Potencia, empuje y duración de maniobra',rf'Un propulsor eléctrico académico recibe {q(P,"W")} con rendimiento cinético 0.60 y escape axial uniforme a {q(ve,"m/s")}. Funciona {q(dur,"s")} sobre un vehículo de masa inicial 450 kg, sin fuerzas externas. Halle empuje, caudal, $I_{{sp}}$, consumo, impulso y delta-v ideal. Compare el empuje al duplicar rapidez con igual potencia.',[g('Pel',P,'W','Potencia eléctrica'),g('eta',eta,'dimensionless','Rendimiento cinético'),g('ve',ve,'m/s','Rapidez uniforme'),g('duration',dur,'s','Duración'),g('m0',m0,'kg','Masa inicial')],'Prestaciones instantáneas e integradas',['Haz axial monocinético, sin presión de salida.','Potencia, velocidad y rendimiento constantes; masa consumida positiva menor que m0.'],'Energía cinética, momento y masa variable',[r'P_j=\eta P_{el}=\dot m v_e^2/2,\quad F=\dot m v_e',r'F=2\eta P_{el}/v_e,\quad \dot m=2\eta P_{el}/v_e^2',r'm_p=\dot mt,\quad I=Ft,\quad \Delta v=v_e\ln[m_0/(m_0-m_p)]'],[rf'La potencia dirigida es {q(eta*P,"W")}. Despejar del balance de energía da $\dot m={num(e["mdot"])}$ kg/s y multiplicar por velocidad produce {q(e["F"],"N")}.',rf'La conversión convencional da $I_{{sp}}={num(e["Isp"])}$ s. En el intervalo se consumen {q(mass,"kg")} y el impulso es {q(imp,"N s")}. La masa final es {q(m0-mass,"kg")}, positiva.',rf'La integración de masa variable da {q(dv,"m/s")}. La aproximación $I/m_0={num(imp/m0)}$ m/s es algo menor porque ignora el incremento de aceleración al reducir masa.',rf'Al duplicar rapidez, el empuje baja a {q(e["F"]/2,"N")} y el caudal a la cuarta parte. No se ha mejorado simultáneamente tiempo de maniobra y consumo.'],rf'$F={num(e["F"])}$ N; $\dot m={num(e["mdot"])}$ kg/s; $m_p={num(mass)}$ kg; $\Delta v={num(dv)}$ m/s.','El impulso específico alto reduce consumo dentro del modelo, pero la potencia limita fuerza. La masa del sistema eléctrico sigue incluida en la masa inicial del vehículo.',rf'$Fv_e/2=\eta P_{{el}}={num(eta*P)}$ W y $I=m_pv_e={num(imp)}$ N s. Para consumo pequeño, la solución logarítmica tiende a $I/m_0$.','No incluye gravedad, variación de potencia, divergencia, masa variable de otros consumibles ni trayectoria orbital real.',[t(rf'2*{eta}*{P}/{ve}',e['F'],'N','2*eta*Pel/ve',{'eta':'dimensionless','Pel':'W','ve':'m/s'}),t(rf'2*{eta}*{P}/{ve}**2',e['mdot'],'kg/s'),t(rf'{ve}*log({m0}/({m0}-{mass}))',dv,'m/s')])

def rocket_case(key,ch,diff,z):
 c=2600+10*z;m0=800+10*z;mf=340+z;dv=delta_v(c,m0,mf);req=1800.;needed=mf*(math.exp(req/c)-1)
 return make(key,ch,diff,'Capacidad de una etapa y masa requerida',rf'Una etapa ideal tiene velocidad efectiva {q(c,"m/s")}, masa inicial {q(m0,"kg")} y final de combustión {q(mf,"kg")}. Halle delta-v y fracción consumida. Para conservar esa masa final y exigir 1800 m/s, determine masa propulsante necesaria.',[g('c',c,'m/s','Velocidad efectiva'),g('m0',m0,'kg','Masa inicial'),g('mf',mf,'kg','Masa final'),g('dvreq',req,'m/s','Objetivo ideal')],'Capacidad ideal y masa inversa',['Rectilíneo sin fuerzas externas; c constante.','Masa final incluye todos los elementos unidos al terminar.'],'Conservación de momento con masa variable',[r'm\,dv=-c\,dm,\quad \Delta v=c\ln(m_0/m_f)',r'm_{0,req}=m_f\exp(\Delta v_{req}/c)',r'm_{p,req}=m_f[\exp(\Delta v_{req}/c)-1]'],[rf'Integrar $dv=-c\,dm/m$ entre las dos masas da $\Delta v={num(c)}\ln({num(m0)}/{num(mf)})={num(dv)}$ m/s.',rf'La masa consumida inicial es {q(m0-mf,"kg")} y su fracción {q((m0-mf)/m0)}. Para el objetivo distinto se despeja exponenciando el cociente adimensional $1800/{num(c)}$.',rf'La nueva masa inicial es {q(mf+needed,"kg")}; restar la masa final da {q(needed,"kg")} de propulsante. Esa masa no debe sumarse a la masa inicial anterior: corresponde a un presupuesto nuevo con la misma masa final.'],rf'$\Delta v={num(dv)}$ m/s; fracción consumida ${num((m0-mf)/m0)}$; $m_{{p,req}}={num(needed)}$ kg.','El resultado es capacidad ideal, no velocidad orbital ni garantía de lanzamiento. Cambiar masa seca o pérdidas cambiaría el presupuesto inverso.',rf'Sustituir $m_{{0,req}}/m_f=\exp(1800/c)$ recupera exactamente 1800 m/s. El logaritmo recibe un cociente positivo mayor que uno.','No hay separación de etapas ni fuerzas externas. La masa final se ha fijado como dato y no se recalcula estructura al cambiar propulsante.',[t(rf'{c}*log({m0}/{mf})',dv,'m/s','c*log(m0/mf)',{'c':'m/s','m0':'kg','mf':'kg'}),t(rf'{mf}*(exp({req}/{c})-1)',needed,'kg')])

def stages(key,ch,diff,z):
 s1=100+z;p1=520+5*z;s2=40.;p2=160+z;L=65.;c1=2450.;c2=2900.;a=s1+p1+s2+p2+L;b=a-p1;d=s2+p2+L;e=s2+L;v1=c1*math.log(a/b);v2=c2*math.log(d/e);wrong=c1*math.log(a/d)+v2
 return make(key,ch,diff,'Dos etapas: separación sin impulso',rf'Un vehículo ideal lleva carga de 65 kg. La primera etapa tiene masa seca {q(s1,"kg")} y propulsante {q(p1,"kg")}, con $c_1=2450$ m/s. La segunda tiene 40 kg secos y {q(p2,"kg")} de propulsante, con $c_2=2900$ m/s. Calcule masas de inicio y fin de cada combustión y delta-v total. Cuantifique el error de retirar la masa seca de primera etapa antes de terminar su combustión.',[g('s1',s1,'kg','Seca primera'),g('p1',p1,'kg','Propulsante primera'),g('s2',s2,'kg','Seca segunda'),g('p2',p2,'kg','Propulsante segunda'),g('L',L,'kg','Carga')],'Masas anidadas y delta-v por etapa',['Etapas en serie, sin pérdidas ni reservas.','Separación sin velocidad relativa; velocidades efectivas constantes.'],'Tsiolkovski por intervalos y contabilidad de masas',[r'm_{01}=s_1+p_1+s_2+p_2+m_L,\quad m_{f1}=s_1+s_2+p_2+m_L',r'm_{02}=s_2+p_2+m_L,\quad m_{f2}=s_2+m_L',r'\Delta v=c_1\ln(m_{01}/m_{f1})+c_2\ln(m_{02}/m_{f2})'],[rf'Antes de la primera combustión hay {q(a,"kg")}. Al agotarla quedan {q(b,"kg")}, incluidos {q(s1,"kg")} secos de esa etapa. Separarla deja {q(d,"kg")}, que es la masa inicial de segunda.',rf'Al terminar la segunda quedan {q(e,"kg")}. Los logaritmos son $2450\ln({num(a)}/{num(b)})={num(v1)}$ m/s y $2900\ln({num(d)}/{num(e)})={num(v2)}$ m/s.',rf'Sumar da {q(v1+v2,"m/s")}. Usar {q(d,"kg")} en el denominador del primer logaritmo daría {q(wrong,"m/s")}, un exceso de {q(wrong-v1-v2,"m/s")}. Ese exceso atribuye a la separación un efecto propulsivo que el modelo no contiene.'],rf'$\Delta v_1={num(v1)}$ m/s; $\Delta v_2={num(v2)}$ m/s; total ${num(v1+v2)}$ m/s.','La segunda etapa acelera una masa inferior gracias al desprendimiento previo. La velocidad no salta al separar masa seca sin impulso.',rf'Las diferencias de masa de cada combustión son exactamente sus propulsantes. La diferencia entre fin de primera y comienzo de segunda es exactamente {q(s1,"kg")}.','No representa consumo paralelo, trayectoria, masa de interetapas no incluida ni variación de prestaciones con ambiente.',[t(rf'{c1}*log({a}/{b})',v1,'m/s'),t(rf'{c2}*log({d}/{e})',v2,'m/s'),t(rf'{v1}+{v2}',v1+v2,'m/s')])

def vertical(key,ch,diff,z):
 m0=400+z;md=2.;dur=50+z*.2;c=2450.;g0=G0;mf=m0-md*dur;ideal=c*math.log(m0/mf);loss=g0*dur;dv=ideal-loss;F=c*md
 return make(key,ch,diff,'Ascenso vertical elemental y duración',rf'Un modelo vertical inicia con masa {q(m0,"kg")}, consume 2 kg/s durante {q(dur,"s")} y tiene $c=2450$ m/s. Considere gravedad constante $g=9.80665$ m/s$^2$, sin resistencia. Halle empuje, masa final, incremento ideal, contribución gravitatoria e incremento de velocidad. Compruebe empuje-peso inicial.',[g('m0',m0,'kg','Masa inicial'),g('mdot',md,'kg/s','Consumo'),g('duration',dur,'s','Duración'),g('c',c,'m/s','Velocidad efectiva'),g('grav',g0,'m/s^2','Gravedad del modelo')],'Incremento real del modelo y viabilidad inicial',['Movimiento vertical y empuje ascendente.','g constante, atmósfera y suelo omitidos; datos elegidos con empuje inicial superior al peso.'],'Ecuación de masa variable con gravedad',[r'm(t)=m_0-\dot m_pt,\quad F=c\dot m_p',r'\dot v=c\dot m_p/m(t)-g',r'v_b-v_0=c\ln[m_0/(m_0-\dot m_pt_b)]-gt_b'],[rf'La masa final es ${num(m0)}-2({num(dur)})={num(mf)}$ kg, positiva. El empuje es $2450\cdot2={num(F)}$ N.',rf'La integral propulsiva vale {q(ideal,"m/s")}. La proyección gravitatoria vertical de este caso es $g t_b={num(loss)}$ m/s, por lo que el incremento neto es {q(dv,"m/s")}.',rf'Inicialmente $F/(m_0g)={num(F/(m0*g0))}>1$. La aceleración inicial es {q(F/m0-g0,"m/s^2")} y la final {q(F/mf-g0,"m/s^2")}. Empuje constante no produce aceleración constante.'],rf'$m_f={num(mf)}$ kg; $\Delta v_{{ideal}}={num(ideal)}$ m/s; $\Delta v_g={num(loss)}$ m/s; $v_b-v_0={num(dv)}$ m/s.','La duración introduce una diferencia respecto a capacidad ideal. Esta velocidad sigue sin demostrar inserción orbital: el movimiento es vertical y el campo se ha simplificado.',rf'Integrar numéricamente $F/(m_0-\dot m t)-g$ debe coincidir con la forma logarítmica. Al hacer $g\to0$ se recupera Tsiolkovski.','El término gt no es una pérdida gravitatoria universal. No se modela curvatura, rotación, resistencia ni guiado.',[t(rf'{c}*log({m0}/{mf})-{g0}*{dur}',dv,'m/s','c*log(m0/(m0-mdot*duration))-grav*duration',{'c':'m/s','m0':'kg','mdot':'kg/s','duration':'s','grav':'m/s^2'}),t(rf'{m0}-{md}*{dur}',mf,'kg')])

def focused(key,ch,diff,z):
 """Casos de mecanismos específicos; valores SI y derivaciones explícitas."""
 if ch==5:
  M=.4;da=-.01;du=da/(M*M-1)
  title='Respuesta local de un conducto subsónico';prompt=r'Una sección académica tiene Mach 0.40. Su área disminuye un 1\,\%. Estime el cambio relativo de rapidez y densidad mediante el modelo diferencial.';giv=[g('Mach',M,'dimensionless','Mach'),g('dArel',da,'dimensionless','Variación área')];eq=[r'dA/A=(M^2-1)du/u',r'du/u=(dA/A)/(M^2-1),\quad d\rho/\rho=-M^2du/u'];steps=[rf'Despejar la velocidad da $(-0.01)/(0.4^2-1)={num(du)}$. Es un aumento de {num(du*100)}\,\%.',rf'La densidad cambia por $-0.4^2({num(du)})={num(-M*M*du)}$, es decir, disminuye aproximadamente {num(M*M*du*100)}\,\%.','Sumar las tres variaciones logarítmicas da cero: la menor área se compensa con rapidez mayor y densidad algo menor.'];result=rf'$du/u\simeq{num(du)}$; $d\rho/\rho\simeq{num(-M*M*du)}$.';check='La continuidad linealizada cierra exactamente; para una variación finita el error es de segundo orden.';tests=[t('(-0.01)/(0.4**2-1)',du)];limit='Sólo una estimación local, lejos de Mach uno; no determina régimen de todo el conducto.'
 elif ch==6:
  eps=2.8+.01*z;ga=1.4;ms=mach_area(eps,ga,'subsonic');mu=mach_area(eps,ga);pb=stagnation_ratios(ms,ga)['p_p0'];crit=(2/(ga+1))**(ga/(ga-1))
  title='Dos raíces y primer bloqueo';prompt=rf'Una tobera ideal tiene $A_e/A_t={num(eps)}$ y $\gamma=1.4$. Calcule las dos raíces de salida para garganta sónica y la contrapresión relativa de primer bloqueo. Compare con una convergente simple.';giv=[g('epsilon',eps,'dimensionless','Expansión'),g('gamma',ga,'dimensionless','Exponente')];eq=[r'A/A^*=f(M,\gamma)',r'(p_b/p_0)_{inicio}=[1+(\gamma-1)M_{e,sub}^2/2]^{-\gamma/(\gamma-1)}'];steps=[rf'La inversión se encierra en dos intervalos distintos: $(0,1)$ y $(1,\infty)$. Las raíces son {q(ms)} y {q(mu)}, respectivamente.',rf'El primer bloqueo usa la raíz subsónica del divergente. Sustituirla da $p_b/p_0={num(pb)}$. Para una convergente simple el umbral sería {q(crit)}.','La diferencia aparece porque el divergente subsónico recupera presión después del mínimo sónico. Ninguno de esos valores es automáticamente la presión adaptada de la rama supersónica.'];result=rf'$M_{{sub}}={num(ms)}$; $M_{{sup}}={num(mu)}$; $(p_b/p_0)_{{inicio}}={num(pb)}$.';check='Sustituir cada raíz en la relación área-Mach recupera la misma expansión dentro de la tolerancia numérica.';tests=[t(rf'(1+0.2*{ms}**2)**(-3.5)',pb)];limit='No se calcula separación ni posición de choque; el umbral es inviscido y cuasiunidimensional.'
 elif ch==9:
  al=math.radians(14);lam=(1+math.cos(al))/2;kin=3000.;press=120.;F=lam*kin+press;cv=.96
  title='Divergencia y definición de rendimiento';prompt='Un modelo de descarga cónica uniforme por ángulo sólido tiene semiángulo de 14 grados. El empuje cinético de referencia es 3000 N y el término de presión 120 N. Halle el empuje axial corregido. Si un coeficiente de velocidad independiente vale 0.96, determine su rendimiento cinético equivalente, sin aplicarlo otra vez al mismo resultado.';giv=[g('alpha',14,'degree','Semiángulo'),g('Fkin',kin,'N','Momento de referencia'),g('Fpress',press,'N','Presión')];eq=[r'\lambda=(1+\cos\alpha)/2,\quad F=\lambda F_{cin}+F_p',r'\eta_n=C_v^2'];steps=[rf'Integrar $\cos\theta$ con peso $\sin\theta$ da $\lambda={num(lam)}$. Se corrige sólo momento axial: ${num(lam)}(3000)+120={num(F)}$ N.',rf'La comparación de velocidades independiente tiene $\eta_n=0.96^2={num(cv**2)}$. No es 0.96 si el rendimiento se define por energía cinética.','No se multiplican ambos factores sobre un empuje ya medido o corregido sin identificar qué pérdidas contiene cada referencia.'];result=rf'$F={num(F)}$ N; $\eta_n={num(cv**2)}$.';check='Para semiángulo cero, lambda vale uno y se recuperan 3120 N. El rendimiento energético permanece menor que el coeficiente de velocidad para valores entre cero y uno.';tests=[t('(1+cos(14*pi/180))/2*3000+120',F,'N'),t('0.96**2',cv**2)];limit='El reparto angular es una idealización; no se predice una tobera real de campana.'
 elif ch==10:
  n=.35;P=1.2;r=P**n
  title='Ley de regresión sin ambigüedad dimensional';prompt=r'Una ley local académica tiene $r_b=r_{ref}(p/p_{ref})^{0.35}$. La presión sube un 20\,\%. Determine la razón de velocidades y la transformación del coeficiente si se escribe la presión numérica en Pa o en MPa.';giv=[g('P',P,'dimensionless','Razón de presión'),g('n',n,'dimensionless','Exponente')];eq=[r'r_2/r_1=(p_2/p_1)^n',r'a_{MPa}=a_{Pa}(10^6)^n'];steps=[rf'La razón de regresión es $1.20^{{0.35}}={num(r)}$, un aumento de {num((r-1)*100)}\,\%.','Para una misma presión física, $p_{Pa}=10^6p_{MPa}$. Sustituir en $r=ap^n$ da $a_{MPa}=a_{Pa}10^{6n}$.',rf'Para el exponente dado, el factor numérico es $10^{{2.1}}={num(10**2.1)}$. No significa un cambio físico de velocidad: compensa la unidad de presión.'];result=rf'$r_2/r_1={num(r)}$; $a_{{MPa}}/a_{{Pa}}={num(10**2.1)}$.';check='El producto coeficiente por presión elevada al exponente es invariante al convertir unidades de forma coherente.';tests=[t('1.2**0.35',r),t('10**(6*0.35)',10**2.1)];limit='El exponente es local; no se extrapola a otro intervalo ni a otro material.'
 elif ch==11:
  Rr=5.;rw=(Rr+1)/2;rv=math.sqrt((Rr*Rr+1)/2)
