CORE={2:thrust,3:thermo,4:uncertainty,7:nozzle_case,8:shock_case,12:solid_case,14:mixture,17:heat,19:pump,21:ep_case,25:rocket_case,26:stages,27:vertical}
def manual():
 return [(CORE.get(ch,focused))(rf'M{ch:02d}',ch,'INTERMEDIATE',ch) for ch in range(3,29)]
def bank():
 groups=[[thrust,thermo,uncertainty,thrust,thermo,uncertainty],[nozzle_case,focused,shock_case,nozzle_case,shock_case,nozzle_case],[solid_case,solid_case,solid_case,solid_case,solid_case,solid_case],[mixture,heat,pump,mixture,pump,heat],[ep_case,ep_case,ep_case,ep_case,ep_case,ep_case],[rocket_case,stages,vertical,stages,rocket_case,vertical]]
 chapters=[[2,3,4,2,3,4],[7,6,8,7,8,7],[12,12,12,12,12,12],[14,17,19,14,19,17],[21,21,21,21,21,21],[25,26,27,26,25,27]]
 diffs=['BASIC','BASIC','INTERMEDIATE','INTERMEDIATE','ADVANCED','EXAM_LEVEL'];rows=[]
 for b,(funcs,chs) in enumerate(zip(groups,chapters),1):
  for j,(fn,ch) in enumerate(zip(funcs,chs)):
   idx=(b-1)*6+j+1;rows.append(fn(rf'P{idx:02d}',ch,diffs[j],idx+2))
 return rows

def exams():
 rows=[]
 for exam in range(1,4):
  part=[]
  for j,(fn,ch) in enumerate([(nozzle_case,7),(solid_case,12),(mixture,14),(ep_case,21),(stages,26)],1):part.append(fn(rf'S{exam}.{j}',ch,'EXAM_LEVEL',30+exam*5+j))
  rows.append(part)
 return rows
if __name__=='__main__':
 data=dict(manual=manual(),bank=bank(),exams=exams());(ROOT/'evidence/problem-data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2));print('Originales:',len(data['manual'])+len(data['bank'])+sum(map(len,data['exams'])),'más M01 y M02 del manuscrito')
